public class PageViewMetricsProcessor
{
    private readonly ConcurrentDictionary<string, long> _viewsByPage = new();
    private readonly ConcurrentDictionary<string, long> _viewsByCountry = new();

    public void Process(PageViewEvent evt)
    {
        Interlocked.Increment(ref _viewsByPage[evt.PageUrl]);
        Interlocked.Increment(ref _viewsByCountry[evt.Country]);
    }

    public IReadOnlyDictionary<string, long> GetPageMetrics() => _viewsByPage;
    public IReadOnlyDictionary<string, long> GetCountryMetrics() => _viewsByCountry;
}

public record PageViewEvent(string PageUrl, string Country, DateTime Timestamp);
